GROUP_KIND_LABELS = {
    "IMMEDIATE": "Family",
    "TEAM": "Team",
    "CIRCLE": "Circle",
    "META": "Network",
}
IMAGE_OPTIMIZATION_SIZE_PRESETS: dict[str, tuple[int, int] | None] = {
    "thumbnail": (150, 150),
    "small": (320, 320),
    "medium": (640, 640),
    "large": (1024, 1024),
    "original": None,
}
IMAGE_OPTIMIZATION_THUMBNAIL_SIZE = (150, 150)
IMAGE_OPTIMIZATION_CACHE_TTL_SECONDS = 60 * 60 * 24
IMAGE_OPTIMIZATION_REUSE_QUALITY_FLOOR = 85
IMAGE_OPTIMIZATION_NAMESPACE = "mobile/optimized"
Image.MAX_IMAGE_PIXELS = 25_000_000


def _image_optimization_cache_key(content_hash: str, size: str, quality: int) -> str:
    return f"mobile:image-optimize:{content_hash}:{size}:{quality}"


def _image_variant_file_key(
    content_hash: str, size: str, quality: int, variant: str
) -> str:
    safe_size = (
        "".join(ch if ch.isalnum() or ch in {"-", "_"} else "-" for ch in size.lower())
        or "original"
    )
    suffix = "" if variant == "optimized" else f"-{variant}"
    return (
        f"{IMAGE_OPTIMIZATION_NAMESPACE}/{content_hash[:2]}/"
        f"{content_hash}-{safe_size}-q{quality}{suffix}.jpg"
    )


def _open_verified_image(image_content: bytes) -> Image.Image:
    with Image.open(io.BytesIO(image_content)) as verification_image:
        verification_image.verify()

    image = Image.open(io.BytesIO(image_content))
    image.load()
    return image


def _prepare_image_for_jpeg(image: Image.Image) -> Image.Image:
    if image.mode in ("RGBA", "LA"):
        rgba_image = image.convert("RGBA")
        background = Image.new("RGB", image.size, (255, 255, 255))
        background.paste(rgba_image, mask=rgba_image.getchannel("A"))
        return background

    if image.mode != "RGB":
        return image.convert("RGB")

    return image.copy()


def _serialize_jpeg(image: Image.Image, quality: int) -> bytes:
    output = io.BytesIO()
    image.save(output, format="JPEG", quality=quality, optimize=True)
    return output.getvalue()


def _build_image_thumbnail(image: Image.Image) -> bytes:
    thumbnail = image.copy()
    thumbnail.thumbnail(IMAGE_OPTIMIZATION_THUMBNAIL_SIZE, Image.Resampling.LANCZOS)
    try:
        return _serialize_jpeg(thumbnail, quality=85)
    finally:
        thumbnail.close()


def _build_storage_url(file_key: str, request_host: str | None) -> str:
    presigned_url = MediaStorageService.generate_presigned_url(
        file_key,
        request_host=request_host,
    )
    if presigned_url:
        return presigned_url

    try:
        return storages["s3uploadEvents"].url(file_key)
    except Exception:
        logger.warning(
            "Falling back to raw storage key for optimized image", exc_info=True
        )
        return file_key


def _load_optimized_variant_metadata(
    optimized_key: str,
    thumbnail_key: str,
    original_size: int,
) -> dict[str, object]:
    storage = storages["s3uploadEvents"]
    optimized_size = storage.size(optimized_key)
    with storage.open(optimized_key, "rb") as optimized_file:
        with Image.open(optimized_file) as optimized_image:
            width, height = optimized_image.size

    return {
        "optimized_key": optimized_key,
        "thumbnail_key": thumbnail_key,
        "original_size": original_size,
        "optimized_size": optimized_size,
        "dimensions": {"width": width, "height": height},
    }


def _build_image_optimization_payload(
    metadata: dict[str, object], request_host: str | None
) -> dict[str, object]:
    optimized_key = str(metadata["optimized_key"])
    thumbnail_key = str(metadata["thumbnail_key"])
    dimensions = cast(dict[str, int], metadata["dimensions"])
    optimized_url = _build_storage_url(optimized_key, request_host)
    thumbnail_url = _build_storage_url(thumbnail_key, request_host)

    return {
        "optimized_url": optimized_url,
        "optimized": optimized_url,
        "thumbnail": thumbnail_url,
        "original_size": int(cast(int, metadata["original_size"])),
        "optimized_size": int(cast(int, metadata["optimized_size"])),
        "dimensions": dimensions,
        "size": [dimensions["width"], dimensions["height"]],
        "format": "JPEG",
    }


def _get_tracking_properties_for_user(user: User) -> dict[str, str]:
    family_id = ""
    if hasattr(user, "profile") and user.profile.primary_family_id:
        family_id = str(user.profile.primary_family_id)

    return {
        "email": user.email,
        "family_id": family_id,
    }


def _track_mobile_auth_success(
    user: User,
    *,
    auth_method: str,
    provider: str | None = None,
    signup: bool = False,
) -> None:
    tracking = get_tracking_client()
    distinct_id = str(user.id)
    properties = {"auth_method": auth_method}
    if provider:
        properties["provider"] = provider

    if signup:
        tracking.track(
            "user_signed_up",
            distinct_id=distinct_id,
            details=TrackingEventDetails(data=properties),
        )

    tracking.track(
        "user_logged_in",
        distinct_id=distinct_id,
        details=TrackingEventDetails(data=properties),
    )
    tracking.identify(
        distinct_id,
        properties=_get_tracking_properties_for_user(user),
    )


def _sync_push_token_to_device_token(
    user: User, push_token: str, device_type: str, client_app: str | None = None
) -> None:
    """Sync a push token from MobileDevice to notifications.DeviceToken.

    The mobile auth flow stores push tokens on mobile.MobileDevice, but the
    notification delivery pipeline reads from notifications.DeviceToken.
    This bridges the two systems.
    """
    from notifications.models import DeviceToken

    # Map mobile device_type values to DeviceToken.DEVICE_TYPE_CHOICES
    type_map = {"ios": "IOS", "android": "ANDROID", "web": "WEB"}
    normalized_type = type_map.get(device_type.lower(), device_type.upper())

    DeviceToken.objects.update_or_create(
        user=user,
        token=push_token,
        defaults={
            "device_type": normalized_type,
            "client_app": canonicalize_client_app(client_app, default=ClientApp.COORD),
            "is_active": True,
        },
    )
    logger.info("Synced push token to DeviceToken for user %s", user.id)


def _first_form_error_message(form: object) -> str:
    errors = getattr(form, "errors", None)
    if errors is not None and hasattr(errors, "get_json_data"):
        json_data = errors.get_json_data()  # type: ignore[union-attr]
        for field_errors in json_data.values():
            if field_errors:
                first = field_errors[0]
                message = first.get("message")
                if isinstance(message, str) and message.strip():
                    return message
    return "Unable to process password reset."


def _get_group_kind(group: object) -> str:
    from users.models import FamilyGroup, FamilyGroupType

    family_group = cast("FamilyGroup", group)
    group_type = getattr(family_group, "group_type", None)
    if group_type is not None:
        return str(group_type.type)

    resolved_group_kind = (
        FamilyGroupType.objects.filter(family=family_group)
        .values_list("type", flat=True)
        .first()
    )
    return str(resolved_group_kind or "IMMEDIATE")


def _serialize_mobile_group(group: object, request: Request) -> dict[str, object]:
    serializer = MobileFamilyGroupReadSerializer(
        context={
            "request": request,
            "request_primary_family_id": cast(
                "User", request.user
            ).profile.primary_family_id,
        }
    )
    return serializer.to_representation(cast(Any, group))


def _set_primary_family(user: User, family: object) -> None:
    target_family = cast(Any, family)
    if user.profile.primary_family_id == target_family.id:
        return
    user.profile.primary_family = target_family
    user.profile.save(update_fields=["primary_family"])


def _get_active_hidden_home_family(user: User) -> Any | None:
    from users.models import FamilyMembership

    memberships = (
        FamilyMembership.objects.filter(
            user=user,
            is_active=True,
            family__is_hidden=True,
            family__archived_at__isnull=True,
        )
        .select_related("family", "family__group_type")
        .order_by("joined_at")
    )

    for membership in memberships:
        if _get_group_kind(membership.family) == "IMMEDIATE":
            return membership.family

    return None


def _archive_hidden_home_family(
    user: User, replacement_family: object | None = None
) -> None:
    hidden_home = _get_active_hidden_home_family(user)
    if hidden_home is None:
        return

    replacement = (
        cast(Any, replacement_family) if replacement_family is not None else None
    )
    if replacement is not None and hidden_home.id == replacement.id:
        return

    hidden_home.archived_at = timezone.now()
    hidden_home.save(update_fields=["archived_at", "updated_at"])

    if replacement is not None and user.profile.primary_family_id == hidden_home.id:
        _set_primary_family(user, replacement)


def _ensure_home_family(user: User) -> Any:
    from users.adapters import create_family_for_user

    immediate_family = get_user_immediate_family(user)
    if immediate_family is not None:
        if user.profile.primary_family_id != immediate_family.id:
            _set_primary_family(user, immediate_family)
        return immediate_family

    created_home_family = create_family_for_user(user, is_hidden=True)
    if created_home_family is None:
        raise RuntimeError("Failed to create compatibility home family")
    return created_home_family


def _eligible_admin_families_for_network(user: User, network: object) -> list[Any]:
    from users.models import FamilyMembership, MetaFamilyMembership

    network_group = cast(Any, network)
    existing_network_family_ids = set(
        MetaFamilyMembership.objects.filter(meta_family=network_group).values_list(
            "family_id", flat=True
        )
    )
    admin_memberships = (
        FamilyMembership.objects.filter(user=user, is_admin=True, is_active=True)
        .select_related("family", "family__group_type")
        .order_by("joined_at")
    )

    eligible_families: list[Any] = []
    for membership in admin_memberships:
        family = membership.family
        if family.id in existing_network_family_ids:
            continue
        if _get_group_kind(family) != "IMMEDIATE":
            continue
        eligible_families.append(family)

    return eligible_families


class MobileAuthViewSet(viewsets.ViewSet):
    """Enhanced authentication for mobile apps with extended sessions."""

    permission_classes = [AllowAny]
    throttle_classes = [DRFScopedRateThrottle]

    @staticmethod
    def _get_client_app(serializer, request: Request) -> str:
        """Resolve client app from serializer data or request context."""
        return canonicalize_client_app(
            serializer.validated_data.get("client_app")
            or getattr(request, "client_app", None),
            default=ClientApp.COORD,
        )

    def get_throttles(self) -> list[BaseThrottle]:
        """Assign scoped throttling for different auth actions."""
        action_scope_map = {
            "login": "mobile-auth",
            "signup": "mobile-signup",
            "google": "mobile-auth",
            "apple": "mobile-auth",
            "biometric_login": "mobile-auth",
            "forgot_password": "mobile-verify-email",
            "reset_password": "mobile-auth",
            "resend_verification": "mobile-verify-email",
            "device_register": "mobile-device",
            "revoke_token": "mobile-device",
        }
        self.throttle_scope = action_scope_map.get(self.action, "mobile-general")
        return super().get_throttles()

    @action(methods=["post"], detail=False)
    def forgot_password(self, request: Request) -> Response:
        """Request a password reset email with a mobile deep link."""
        serializer = MobileForgotPasswordSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        email = serializer.validated_data["email"].strip().lower()
        mobile_deep_link_base = resolve_password_reset_mobile_deep_link_base(
            serializer.validated_data.get("deep_link_base")
        )
        users = filter_users_by_email(email, is_active=True, prefer_verified=True)
        request._request._mobile_reset_deep_link_base = mobile_deep_link_base  # type: ignore[attr-defined]

        try:
            with allauth_context.request_context(request._request):
                account_flows.password_reset.request_password_reset(
                    request._request,
                    email,
                    users,
                    None,
                )
        except Exception:
            logger.exception("Failed to initiate mobile password reset for %s", email)
            return Response(
                {"error": "Failed to send password reset email."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )
        finally:
            if hasattr(request._request, "_mobile_reset_deep_link_base"):
                delattr(request._request, "_mobile_reset_deep_link_base")

        return Response({"ok": True})

    @action(methods=["post"], detail=False)
    def reset_password(self, request: Request) -> Response:
        """Validate an opaque reset token and set a new password."""
        serializer = MobileResetPasswordSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        opaque_token = serializer.validated_data["token"].strip()
        new_password = serializer.validated_data["new_password"]
        uidb36, separator, key = opaque_token.partition("-")
        if not separator or not uidb36 or not key:
            return Response(
                {"error": "Invalid or expired key."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            with allauth_context.request_context(request._request):
                token_form = UserTokenForm(data={"uidb36": uidb36, "key": key})
                if not token_form.is_valid():
                    return Response(
                        {"error": _first_form_error_message(token_form)},
                        status=status.HTTP_400_BAD_REQUEST,
                    )

                reset_form = ResetPasswordKeyForm(
                    data={"password1": new_password, "password2": new_password},
                    user=token_form.reset_user,
                    temp_key=key,
                )
                if not reset_form.is_valid():
                    return Response(
                        {"error": _first_form_error_message(reset_form)},
                        status=status.HTTP_400_BAD_REQUEST,
                    )

                reset_form.save()
                account_flows.password_reset.finalize_password_reset(
                    request._request,
                    token_form.reset_user,
                    email=token_form.reset_user.email,
                )
        except Exception:
            logger.exception("Failed to complete mobile password reset")
            return Response(
                {"error": "Failed to reset password."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        return Response({"ok": True})

    @action(methods=["post"], detail=False)
    def login(self, request: Request) -> Response:
        """Mobile login with extended refresh token lifetime."""
        serializer = MobileLoginSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        email = serializer.validated_data["email"]
        password = serializer.validated_data["password"]
        device_id = serializer.validated_data["device_id"]
        device_name = serializer.validated_data.get("device_name", "")
        device_type = serializer.validated_data["device_type"]
        extended_session = serializer.validated_data["extended_session"]
        push_token = serializer.validated_data.get("push_token", "")
        client_app = self._get_client_app(serializer, request)

        # Authenticate user
        user = authenticate(username=email, password=password)
        if not user:
            return Response(
                {"error": "Invalid credentials"}, status=status.HTTP_401_UNAUTHORIZED
            )

        try:
            with transaction.atomic():
                # Register or update device
                device, created = MobileDevice.objects.update_or_create(
                    device_id=device_id,
                    defaults={
                        "user": user,
                        "device_name": device_name,
                        "device_type": device_type,
                        "last_login": timezone.now(),
                        "extended_session": extended_session,
                        "push_token": push_token,
                        "client_app": client_app,
                    },
                )

                # Sync push token to notification delivery pipeline
                if push_token:
                    _sync_push_token_to_device_token(
                        user, push_token, device_type, client_app
                    )

                # Generate tokens with extended lifetime for mobile
                refresh_lifetime = timedelta(days=365 if extended_session else 180)

                refresh = RefreshToken.for_user(user)

                # Add custom claims to token
                refresh["device_id"] = device_id
                refresh["extended"] = extended_session
                refresh["device_type"] = device_type

                # Set custom expiration for extended sessions BEFORE extracting JTI
                if extended_session:
                    refresh.set_exp(lifetime=refresh_lifetime)
                    refresh_expiry = timezone.now() + refresh_lifetime
                else:
                    # Use the token's actual expiry for non-extended sessions
                    from datetime import datetime

                    refresh_expiry = timezone.make_aware(
                        datetime.fromtimestamp(int(refresh["exp"]))
                    )

                # Create or update mobile session using the actual token JTI
                jti = str(
                    refresh["jti"]
                )  # Use direct access to ensure we get the correct JTI

                MobileSession.objects.update_or_create(
                    device=device,
                    refresh_token_jti=jti,
                    defaults={
                        "refresh_token_expiry": refresh_expiry,
                        "is_active": True,
                        "last_refreshed": timezone.now(),
                    },
                )

                response_data = {
                    "access": str(refresh.access_token),
                    "refresh": str(refresh),
                    "user": UserSerializer(user).data,
                    "refresh_expires_in": int(refresh_lifetime.total_seconds()),
                    "device": MobileDeviceSerializer(device).data,
                }
                transaction.on_commit(
                    lambda user=user: _track_mobile_auth_success(  # type: ignore[misc]
                        user,
                        auth_method="email",
                    )
                )

                logger.info(
                    f"Mobile login successful for user {user.id} on device {device_id}"
                )
                return Response(response_data, status=status.HTTP_200_OK)

        except Exception as e:
            logger.error(f"Mobile login failed: {str(e)}")
            return Response(
                {"error": "Login failed"}, status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )

    @action(methods=["post"], detail=False)
    def signup(self, request: Request) -> Response:
        """Mobile signup with optional home-group creation and device registration."""
        from users.adapters import create_family_for_user
        from users.services.email_addresses import ensure_email_address

        user_model = get_user_model()

        serializer = MobileSignupSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        email = serializer.validated_data["email"]
        password = serializer.validated_data["password"]
        first_name = serializer.validated_data.get("first_name", "")
        last_name = serializer.validated_data.get("last_name", "")
        phone_number = serializer.validated_data.get("phone_number")
        create_home_group = serializer.validated_data.get("create_home_group", True)
        device_id = serializer.validated_data["device_id"]
        device_name = serializer.validated_data.get("device_name", "")
        device_type = serializer.validated_data["device_type"]
        push_token = serializer.validated_data.get("push_token", "")
        client_app = self._get_client_app(serializer, request)

        try:
            with transaction.atomic():
                # Generate username from email
                username = email.split("@")[0]
                base_username = username
                counter = 1
                while user_model.objects.filter(username=username).exists():
                    username = f"{base_username}{counter}"
                    counter += 1

                # Create user
                user = user_model.objects.create_user(
                    username=username,
                    email=email,
                    password=password,
                    first_name=first_name,
                    last_name=last_name,
                )

                ensure_email_address(user=user, email=user.email, verified=False)
                try:
                    from allauth.account.models import EmailAddress
                except Exception:  # pragma: no cover
                    EmailAddress = None  # type: ignore[assignment]  # noqa: N806

                if EmailAddress is not None:
                    email_address = EmailAddress.objects.filter(
                        user=user, email=user.email
                    ).first()
                    if email_address:
                        try:
                            email_address.send_confirmation(
                                request._request, signup=True
                            )
                        except Exception:
                            logger.exception(
                                "Failed to send signup email verification for user %s",
                                user.id,
                            )

                # Create user profile with phone number
                profile, _ = UserProfile.objects.get_or_create(user=user)
                if phone_number:
                    profile.phone_number = phone_number
                    profile.save(update_fields=["phone_number"])

                if create_home_group:
                    family = create_family_for_user(user)
                    if not family:
                        logger.error(f"Failed to create family for user {user.id}")
                        raise Exception("Failed to create family")

                queue_user_signup_webhook(str(user.id))

                # Register device
                device, _ = MobileDevice.objects.update_or_create(
                    device_id=device_id,
                    defaults={
                        "user": user,
                        "device_name": device_name,
                        "device_type": device_type,
                        "last_login": timezone.now(),
                        "extended_session": True,  # Default to extended for new signups
                        "push_token": push_token,
                        "client_app": client_app,
                    },
                )

                # Sync push token to notification delivery pipeline
                if push_token:
                    _sync_push_token_to_device_token(
                        user, push_token, device_type, client_app
                    )

                # Generate tokens with extended lifetime
                refresh_lifetime = timedelta(days=365)
                refresh = RefreshToken.for_user(user)

                # Add custom claims
                refresh["device_id"] = device_id
                refresh["extended"] = True
                refresh["device_type"] = device_type

                # Set custom expiration
                refresh.set_exp(lifetime=refresh_lifetime)
                refresh_expiry = timezone.now() + refresh_lifetime

                # Create mobile session
                jti = str(refresh["jti"])
                MobileSession.objects.update_or_create(
                    device=device,
                    refresh_token_jti=jti,
                    defaults={
                        "refresh_token_expiry": refresh_expiry,
                        "is_active": True,
                        "last_refreshed": timezone.now(),
                    },
                )

                response_data = {
                    "access": str(refresh.access_token),
                    "refresh": str(refresh),
                    "user": UserSerializer(user).data,
                    "refresh_expires_in": int(refresh_lifetime.total_seconds()),
                    "device": MobileDeviceSerializer(device).data,
                }
                transaction.on_commit(
                    lambda user=user: _track_mobile_auth_success(  # type: ignore[misc]
                        user,
                        auth_method="email",
                        signup=True,
                    )
                )

                logger.info(
                    f"Mobile signup successful for user {user.id} on device {device_id}"
                )
                return Response(response_data, status=status.HTTP_201_CREATED)

        except Exception as e:
            logger.error("Mobile signup failed: %s", e, exc_info=True)
            error_msg = (
                "An account with this email already exists."
                if "already exists" in str(e)
                else "Signup failed. Please try again."
            )
            return Response(
                {"error": error_msg},
                status=status.HTTP_400_BAD_REQUEST,
            )

    @action(methods=["post"], detail=False, permission_classes=[IsAuthenticated])
    def resend_verification(self, request: Request) -> Response:
        """Resend email verification for the authenticated user (mobile)."""
        from django.core.cache import cache

        from users.services.email_addresses import (
            ensure_email_address,
            is_user_email_verified,
        )

        user = cast("User", request.user)
        if is_user_email_verified(user):
            return Response({"ok": True, "already_verified": True})

        cache_key = f"resend_verification_{user.id}"
        if cache.get(cache_key):
            return Response(
                {"error": "Please wait a few minutes before resending verification."},
                status=status.HTTP_429_TOO_MANY_REQUESTS,
            )

        # Reserve cooldown slot before sending to prevent TOCTOU race
        cache.set(cache_key, True, timeout=300)

        ensure_email_address(user=user, email=user.email, verified=False)
        try:
            from allauth.account.models import EmailAddress
        except ImportError:  # pragma: no cover
            EmailAddress = None  # type: ignore[assignment]  # noqa: N806

        if EmailAddress is None:
            cache.delete(cache_key)
            return Response(
                {"error": "Email verification is not available."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        email_address = EmailAddress.objects.filter(
            user=user, email=user.email.strip().lower()
        ).first()
        if not email_address:
            cache.delete(cache_key)
            return Response(
                {"error": "No email address found for your account."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            email_address.send_confirmation(request._request, signup=False)
        except Exception:
            cache.delete(cache_key)  # Release on failure
            logger.exception("Failed to resend email verification for user %s", user.id)
            return Response(
                {"error": "Failed to resend verification email."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        return Response({"ok": True})

    @action(methods=["post"], detail=False)
    def google(self, request: Request) -> Response:
        """Google OAuth login for mobile apps."""
        serializer = MobileGoogleLoginSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        id_token = serializer.validated_data["id_token"]
        device_id = serializer.validated_data["device_id"]
        device_name = serializer.validated_data.get("device_name", "")
        device_type = serializer.validated_data["device_type"]
        push_token = serializer.validated_data.get("push_token", "")
        create_home_group = serializer.validated_data.get("create_home_group", True)
        client_app = self._get_client_app(serializer, request)

        try:
            # Import here to avoid circular dependencies
            from google.auth.transport import requests
            from google.oauth2 import id_token as google_id_token

            from users.adapters import create_family_for_user
            from users.services.email_addresses import ensure_email_address

            user_model = get_user_model()

            # Verify the Google ID token
            try:
                # Get the client ID from settings
                from allauth.socialaccount.models import SocialApp
                from django.conf import settings

                # Try to get the Google app configuration
                try:
                    google_app = SocialApp.objects.get(provider="google")
                    client_id = google_app.client_id
                except SocialApp.DoesNotExist:
                    # Fallback to settings if configured
                    client_id = getattr(settings, "GOOGLE_OAUTH_CLIENT_ID", None)
                    if not client_id:
                        return Response(
                            {"error": "Google OAuth not configured"},
                            status=status.HTTP_500_INTERNAL_SERVER_ERROR,
                        )

                # Verify the token
                idinfo = google_id_token.verify_oauth2_token(  # type: ignore[no-untyped-call]
                    id_token,
                    requests.Request(),  # type: ignore[no-untyped-call]
                    client_id,
                )

                # Extract user info
                email = idinfo.get("email")
                email_verified = idinfo.get("email_verified", False)
                first_name = idinfo.get("given_name", "")
                last_name = idinfo.get("family_name", "")
                google_id = idinfo["sub"]

                if not email_verified:
                    return Response(
                        {"error": "Email not verified with Google"},
                        status=status.HTTP_400_BAD_REQUEST,
                    )

            except ValueError as e:
                logger.error(f"Invalid Google ID token: {str(e)}")
                return Response(
                    {"error": "Invalid Google ID token"},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            with transaction.atomic():
                # Check if user exists
                user = user_model.objects.filter(email=email).first()
                created_user = False

                if not user:
                    # Create new user
                    username = email.split("@")[0]
                    # Ensure unique username
                    base_username = username
                    counter = 1
                    while user_model.objects.filter(username=username).exists():
                        username = f"{base_username}{counter}"
                        counter += 1

                    user = user_model.objects.create_user(
                        username=username,
                        email=email,
                        first_name=first_name,
                        last_name=last_name,
                    )
                    user.set_unusable_password()  # No password for OAuth users
                    user.save()

                    if create_home_group:
                        create_family_for_user(user)
                    created_user = True

                    logger.info(f"Created new user via Google OAuth: {user.id}")
                else:
                    # Update user info if needed
                    if not user.first_name and first_name:
                        user.first_name = first_name
                    if not user.last_name and last_name:
                        user.last_name = last_name
                    user.save()

                ensure_email_address(user=user, email=str(email), verified=True)

                # Link Google account to user via allauth if not already linked
                from allauth.socialaccount.models import SocialAccount

                social_account, created = SocialAccount.objects.get_or_create(
                    user=user,
                    provider="google",
                    defaults={
                        "uid": google_id,
                        "extra_data": idinfo,
                    },
                )

                if not created:
                    # Update extra data
                    social_account.extra_data = idinfo
                    social_account.save()

                if created_user:
                    queue_user_signup_webhook(str(user.id))
                    transaction.on_commit(
                        lambda: enqueue_onboarding_emails_for_user(user)
                    )

                # Register or update device
                device, created = MobileDevice.objects.update_or_create(
                    device_id=device_id,
                    defaults={
                        "user": user,
                        "device_name": device_name,
                        "device_type": device_type,
                        "last_login": timezone.now(),
                        "extended_session": True,  # Google login implies extended session
                        "push_token": push_token,
                        "client_app": client_app,
                    },
                )

                # Sync push token to notification delivery pipeline
                if push_token:
                    _sync_push_token_to_device_token(
                        user, push_token, device_type, client_app
                    )

                # Generate tokens with extended lifetime
                refresh_lifetime = timedelta(days=365)  # Extended for OAuth logins
                refresh = RefreshToken.for_user(user)

                # Add custom claims
                refresh["device_id"] = device_id
                refresh["extended"] = True
                refresh["device_type"] = device_type
                refresh["auth_method"] = "google"

                # Set custom expiration
                refresh.set_exp(lifetime=refresh_lifetime)
                refresh_expiry = timezone.now() + refresh_lifetime

                # Create or update mobile session
                jti = str(refresh["jti"])

                MobileSession.objects.update_or_create(
                    device=device,
                    refresh_token_jti=jti,
                    defaults={
                        "refresh_token_expiry": refresh_expiry,
                        "is_active": True,
                        "last_refreshed": timezone.now(),
                    },
                )

                # Resolve a consistent primary family for mobile clients.
                primary_family = get_user_immediate_family(user)
                if primary_family and (
                    not user.profile.primary_family
                    or user.profile.primary_family_id != primary_family.id
                ):
                    user.profile.primary_family = primary_family
                    user.profile.save(update_fields=["primary_family"])

                user_data = UserSerializer(user).data
                user_data["primary_family"] = (
                    str(primary_family.id) if primary_family else None
                )

                response_data = {
                    "access": str(refresh.access_token),
                    "refresh": str(refresh),
                    "session_expiry": int(refresh_lifetime.total_seconds()),
                    "user": user_data,
                    "device_id": device_id,
                }
                transaction.on_commit(
                    lambda user=user,  # type: ignore[misc]
                    created_user=created_user: _track_mobile_auth_success(
                        user,
                        auth_method="social",
                        provider="google",
                        signup=created_user,
                    )
                )

                logger.info(
                    f"Google OAuth login successful for user {user.id} on device {device_id}"
                )
                return Response(response_data, status=status.HTTP_200_OK)

        except Exception as e:
            logger.error(f"Google OAuth login failed: {str(e)}")
            return Response(
                {"error": "Google login failed"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(methods=["post"], detail=False)
    def apple(self, request: Request) -> Response:
        """Apple OAuth login for mobile apps."""
        serializer = MobileAppleLoginSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        identity_token = serializer.validated_data.get("identity_token")
        authorization_code = serializer.validated_data.get("authorization_code")
        nonce = serializer.validated_data.get("nonce")
        device_id = serializer.validated_data["device_id"]
        device_name = serializer.validated_data.get("device_name", "")
        device_type = serializer.validated_data["device_type"]
        push_token = serializer.validated_data.get("push_token", "")
        create_home_group = serializer.validated_data.get("create_home_group", True)
        client_app = self._get_client_app(serializer, request)

        try:
            from allauth.socialaccount.models import SocialAccount

            from family_scheduler import apple_signin
            from users.adapters import create_family_for_user
            from users.services.email_addresses import ensure_email_address

            user_model = get_user_model()

            if authorization_code and not identity_token:
                client_secret = apple_signin.get_apple_client_secret()
                service_id = (
                    getattr(settings, "APPLE_SERVICE_ID", "") or "com.clancal.web"
                )
                redirect_uri = getattr(settings, "APPLE_ANDROID_REDIRECT_URI", "")
                token_response = apple_signin.exchange_apple_code(
                    authorization_code,
                    redirect_uri,
                    client_secret,
                    service_id,
                )
                identity_token = token_response.get("id_token")

            if not identity_token:
                return Response(
                    {"error": "Missing Apple identity token"},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            if device_type == "android":
                audience = (
                    getattr(settings, "APPLE_SERVICE_ID", "") or "com.clancal.web"
                )
            else:
                # Accept multiple iOS bundle IDs (comma-separated) so all
                # app variants (coordination, organize, home) can sign in.
                # PyJWT accepts a list for the audience parameter.
                raw = getattr(settings, "APPLE_IOS_BUNDLE_ID", "") or "com.clancal.app"
                parts = [p.strip() for p in raw.split(",") if p.strip()]
                audience = parts if len(parts) > 1 else parts[0]

            claims = apple_signin.verify_apple_identity_token(
                identity_token, audience=audience, nonce=nonce
            )

            email = claims.get("email")
            email_verified = claims.get("email_verified", True)
            if isinstance(email_verified, str):
                email_verified = email_verified.lower() == "true"

            apple_id = claims.get("sub")
            if not apple_id:
                return Response(
                    {"error": "Invalid Apple identity token"},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            if email and not email_verified:
                return Response(
                    {"error": "Email not verified with Apple"},
                    status=status.HTTP_400_BAD_REQUEST,
                )

            with transaction.atomic():
                user = None
                created_user = False
                if email:
                    user = user_model.objects.filter(email=email).first()

                if not user:
                    existing_account = (
                        SocialAccount.objects.filter(provider="apple", uid=apple_id)
                        .select_related("user")
                        .first()
                    )
                    if existing_account:
                        user = existing_account.user

                if not user and not email:
                    return Response(
                        {
                            "error": "Apple account is not linked. Please sign in with email first."
                        },
                        status=status.HTTP_400_BAD_REQUEST,
                    )

                if not user:
                    email_str = str(email)
                    username = email_str.split("@")[0]
                    base_username = username
                    counter = 1
                    while user_model.objects.filter(username=username).exists():
                        username = f"{base_username}{counter}"
                        counter += 1

                    user = user_model.objects.create_user(
                        username=username,
                        email=email_str,
                        first_name=claims.get("given_name", ""),
                        last_name=claims.get("family_name", ""),
                    )
                    user.set_unusable_password()
                    user.save()

                    if create_home_group:
                        create_family_for_user(user)
                    queue_user_signup_webhook(str(user.id))
                    created_user = True

                social_account, created = SocialAccount.objects.get_or_create(
                    user=user,
                    provider="apple",
                    defaults={
                        "uid": apple_id,
                        "extra_data": claims,
                    },
                )

                if not created:
                    social_account.uid = apple_id
                    social_account.extra_data = claims
                    social_account.save()

                should_mark_verified = bool(email and email_verified)
                ensure_email_address(
                    user=user,
                    email=str(email) if email else user.email,
                    verified=should_mark_verified,
                )
                if created_user:
                    transaction.on_commit(
                        lambda: enqueue_onboarding_emails_for_user(user)
                    )

                device, created = MobileDevice.objects.update_or_create(
                    device_id=device_id,
                    defaults={
                        "user": user,
                        "device_name": device_name,
                        "device_type": device_type,
                        "last_login": timezone.now(),
                        "extended_session": True,
                        "push_token": push_token,
                        "client_app": client_app,
                    },
                )

                # Sync push token to notification delivery pipeline
                if push_token:
                    _sync_push_token_to_device_token(
                        user, push_token, device_type, client_app
                    )

                refresh_lifetime = timedelta(days=365)
                refresh = RefreshToken.for_user(user)
                refresh["device_id"] = device_id
                refresh["extended"] = True
                refresh["device_type"] = device_type
                refresh["auth_method"] = "apple"

                refresh.set_exp(lifetime=refresh_lifetime)
                refresh_expiry = timezone.now() + refresh_lifetime

                jti = str(refresh["jti"])
                MobileSession.objects.update_or_create(
                    device=device,
                    refresh_token_jti=jti,
                    defaults={
                        "refresh_token_expiry": refresh_expiry,
                        "is_active": True,
                        "last_refreshed": timezone.now(),
                    },
                )

                primary_family = get_user_immediate_family(user)
                if primary_family and (
                    not user.profile.primary_family
                    or user.profile.primary_family_id != primary_family.id
                ):
                    user.profile.primary_family = primary_family
                    user.profile.save(update_fields=["primary_family"])

                user_data = UserSerializer(user).data
                user_data["primary_family"] = (
                    str(primary_family.id) if primary_family else None
                )

                response_data = {
                    "access": str(refresh.access_token),
                    "refresh": str(refresh),
                    "session_expiry": int(refresh_lifetime.total_seconds()),
                    "user": user_data,
                    "device_id": device_id,
                }
                transaction.on_commit(
                    lambda user=user,  # type: ignore[misc]
                    created_user=created_user: _track_mobile_auth_success(
                        user,
                        auth_method="social",
                        provider="apple",
                        signup=created_user,
                    )
                )

                logger.info(
                    f"Apple OAuth login successful for user {user.id} on device {device_id}"
                )
                return Response(response_data, status=status.HTTP_200_OK)

        except Exception as e:
            logger.error(f"Apple OAuth login failed: {str(e)}")
            return Response(
                {"error": "Apple login failed"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(methods=["post"], detail=False)
    def biometric_login(self, request: Request) -> Response:
        """Quick login with biometric + stored refresh token."""
        serializer = BiometricLoginSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        refresh_token = serializer.validated_data["refresh_token"]
        device_id = serializer.validated_data["device_id"]

        try:
            refresh = RefreshToken(refresh_token)

            # Verify device ID matches
            if refresh.get("device_id") != device_id:
                raise TokenError("Device mismatch")

            # Check if session is still active
            device = MobileDevice.objects.get(device_id=device_id)
            session = MobileSession.objects.filter(
                device=device,
                refresh_token_jti=str(refresh["jti"]),
                is_active=True,
            ).first()

            if not session or session.is_expired():
                raise TokenError("Session expired")

            # Generate new access token
            user = refresh.user  # type: ignore[attr-defined]
            response_data = {
                "access": str(refresh.access_token),
                "user": UserSerializer(user).data,
            }
            _track_mobile_auth_success(
                user,
                auth_method="biometric",
            )

            # Update last login time
            device.last_login = timezone.now()
            device.save(update_fields=["last_login"])

            logger.info(
                f"Biometric login successful for user {user.id} on device {device_id}"
            )
            return Response(response_data, status=status.HTTP_200_OK)

        except (TokenError, MobileDevice.DoesNotExist) as e:
            logger.warning(f"Biometric login failed: {str(e)}")
            return Response(
                {"error": "Invalid token or device"},
                status=status.HTTP_401_UNAUTHORIZED,
            )

