    @action(methods=["post"], detail=False, permission_classes=[IsAuthenticated])
    def check_referral_code(self, request: Request) -> Response:
        """Check if a referral code points to a family, team, circle, or network."""
        from users.models import FamilyGroup, FamilyMembership, MetaFamilyMembership

        from .serializers import CheckReferralCodeSerializer

        serializer = CheckReferralCodeSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        code = serializer.validated_data["code"]

        try:
            group = FamilyGroup.objects.get(referral_code=code)
        except FamilyGroup.DoesNotExist:
            return Response(
                {"error": "Invalid referral code"}, status=status.HTTP_404_NOT_FOUND
            )

        group_kind = _get_group_kind(group)
        if group_kind == "EXTENDED":
            group_kind = "IMMEDIATE"
        group_label = GROUP_KIND_LABELS.get(group_kind, "Group")

        if group_kind == "META":
            admin_families = _eligible_admin_families_for_network(
                cast("User", request.user), group
            )
            family_count = MetaFamilyMembership.objects.filter(
                meta_family=group
            ).count()
            admin_families_payload = [
                {"id": str(family.id), "name": family.name} for family in admin_families
            ]

            return Response(
                {
                    "type": group_kind,
                    "group_kind": group_kind,
                    "group_name": group.name,
                    "group_label": group_label,
                    "network_name": group.name,
                    "family_count": family_count,
                    "requires_family_selection": len(admin_families_payload) > 1,
                    "user_admin_families": admin_families_payload,
                }
            )

        is_member = FamilyMembership.objects.filter(
            user=cast("User", request.user), family=group, is_active=True
        ).exists()
        if is_member:
            return Response(
                {"error": f"You are already a member of this {group_label.lower()}"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        member_count = FamilyMembership.objects.filter(
            family=group, is_active=True
        ).count()
        return Response(
            {
                "type": group_kind,
                "group_kind": group_kind,
                "group_name": group.name,
                "group_label": group_label,
                "family_name": group.name if group_kind == "IMMEDIATE" else None,
                "member_count": member_count,
                "requires_family_selection": False,
                "user_admin_families": [],
            }
        )

    @action(methods=["post"], detail=False, permission_classes=[IsAuthenticated])
    def join_by_code(self, request: Request) -> Response:
        """Join a family, team, circle, or network using a referral code."""
        from users.models import FamilyGroup, FamilyMembership, MetaFamilyMembership

        from .serializers import JoinByCodeSerializer

        serializer = JoinByCodeSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        code = serializer.validated_data["code"]
        family_id = serializer.validated_data.get("family_id")

        try:
            group = FamilyGroup.objects.get(referral_code=code)
        except FamilyGroup.DoesNotExist:
            return Response(
                {"error": "Invalid referral code"}, status=status.HTTP_404_NOT_FOUND
            )

        group_kind = _get_group_kind(group)
        if group_kind == "EXTENDED":
            group_kind = "IMMEDIATE"
        group_label = GROUP_KIND_LABELS.get(group_kind, "Group")

        try:
            with transaction.atomic():
                if group_kind == "META":
                    admin_families = _eligible_admin_families_for_network(
                        cast("User", request.user), group
                    )
                    if not admin_families:
                        return Response(
                            {
                                "error": "You need an immediate family before joining this network."
                            },
                            status=status.HTTP_400_BAD_REQUEST,
                        )

                    if family_id:
                        family_to_connect = next(
                            (
                                family
                                for family in admin_families
                                if str(family.id) == str(family_id)
                            ),
                            None,
                        )
                        if not family_to_connect:
                            return Response(
                                {
                                    "error": "You are not an admin of the specified family"
                                },
                                status=status.HTTP_400_BAD_REQUEST,
                            )
                    elif len(admin_families) == 1:
                        family_to_connect = admin_families[0]
                    else:
                        return Response(
                            {
                                "error": "family_id required when you admin multiple families"
                            },
                            status=status.HTTP_400_BAD_REQUEST,
                        )

                    # Check if already connected
                    if MetaFamilyMembership.objects.filter(
                        family=family_to_connect, meta_family=group
                    ).exists():
                        return Response(
                            {"error": "Your family is already part of this network"},
                            status=status.HTTP_400_BAD_REQUEST,
                        )

                    if not family_to_connect:
                        return Response(
                            {"error": "No family found to connect"},
                            status=status.HTTP_400_BAD_REQUEST,
                        )

                    # Create the connection
                    MetaFamilyMembership.objects.create(
                        family=family_to_connect, meta_family=group
                    )

                    logger.info(
                        "Family %s joined network %s via code by user %s",
                        family_to_connect.id,
                        group.id,
                        request.user.id,
                    )

                    return Response(
                        {
                            "type": group_kind,
                            "group_kind": group_kind,
                            "message": f"Successfully connected {family_to_connect.name} to {group.name}",
                            "joined_group": _serialize_mobile_group(group, request),
                            "home_family": _serialize_mobile_group(
                                family_to_connect, request
                            ),
                        }
                    )

                if FamilyMembership.objects.filter(
                    user=cast("User", request.user), family=group, is_active=True
                ).exists():
                    return Response(
                        {
                            "error": f"You are already a member of this {group_label.lower()}"
                        },
                        status=status.HTTP_400_BAD_REQUEST,
                    )

                FamilyMembership.objects.create(
                    user=cast("User", request.user),
                    family=group,
                    role="MEMBER" if group_kind in {"TEAM", "CIRCLE"} else "OTHER",
                    is_admin=False,
                )

                if group_kind == "IMMEDIATE":
                    archived_home_family = _get_active_hidden_home_family(
                        cast("User", request.user)
                    )
                    success, error = assign_primary_family(
                        cast("User", request.user), group, transaction_safe=False
                    )
                    if not success:
                        return Response(
                            {"error": error or "Failed to join family"},
                            status=status.HTTP_400_BAD_REQUEST,
                        )
                    _archive_hidden_home_family(cast("User", request.user), group)
                    home_family = group
                else:
                    archived_home_family = None
                    home_family = _ensure_home_family(cast("User", request.user))

                logger.info(
                    "User %s joined %s %s via code",
                    request.user.id,
                    group_label.lower(),
                    group.id,
                )

                return Response(
                    {
                        "type": group_kind,
                        "group_kind": group_kind,
                        "message": f"Successfully joined {group.name}",
                        "joined_group": _serialize_mobile_group(group, request),
                        "home_family": _serialize_mobile_group(home_family, request),
                        "archived_home_family_id": (
                            str(archived_home_family.id)
                            if archived_home_family is not None
                            else None
                        ),
                    }
                )

        except Exception as e:
            logger.error(f"Join by code failed: {str(e)}")
            return Response(
                {"error": "Failed to join. Please try again."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(
        detail=False,
        methods=["post"],
        url_path="onboarding/update",
        permission_classes=[IsAuthenticated],
    )
    def update_onboarding(self, request: Request) -> Response:
        """Update user's onboarding status from mobile app."""
        user = cast("User", request.user)

        # Validate request data using serializer
        serializer = OnboardingUpdateSerializer(data=request.data)
        if not serializer.is_valid():
            return Response(
                {"error": serializer.errors},
                status=status.HTTP_400_BAD_REQUEST,
            )

        validated_data = serializer.validated_data

        try:
            with transaction.atomic():
                # Handle UserProfile.DoesNotExist gracefully
                # Use get_or_create to handle both existing and missing profiles
                profile, profile_created = UserProfile.objects.get_or_create(user=user)

                # Track which fields are modified for optimized save
                update_fields = []

                if "user_intent" in validated_data and validated_data["user_intent"]:
                    profile.onboarding_user_intent = validated_data["user_intent"]
                    update_fields.append("onboarding_user_intent")

                derived_track = derive_onboarding_track(profile)
                if profile.onboarding_track != derived_track:
                    profile.onboarding_track = derived_track
                    update_fields.append("onboarding_track")

                # Auto-enable trips feature when onboarding derives vacation_first track
                if derived_track == "vacation_first":
                    family = profile.primary_family
                    if family and hasattr(family, "feature_settings"):
                        family.feature_settings.enable_trips()

                if validated_data.get("calendar_connected"):
                    profile.calendar_connected_at = timezone.now()
                    update_fields.append("calendar_connected_at")

                if validated_data.get("completed"):
                    profile.onboarding_completed = True
                    profile.onboarding_completed_at = timezone.now()
                    update_fields.extend(
                        ["onboarding_completed", "onboarding_completed_at"]
                    )
                    logger.info(
                        f"User {user.id} completed onboarding with intent: {profile.onboarding_user_intent}"
                    )

                if validated_data.get("skipped"):
                    profile.onboarding_skipped_at = timezone.now()
                    update_fields.append("onboarding_skipped_at")
                    logger.info(f"User {user.id} skipped onboarding")

                # Only save if fields were modified
                if update_fields:
                    if profile_created:
                        # Full save for newly created profiles (update_fields fails)
                        profile.save()
                    else:
                        # Optimized save for existing profiles
                        profile.save(update_fields=update_fields)
                    if "onboarding_track" in update_fields:
                        sync_pending_onboarding_track_for_user(
                            user, profile.onboarding_track
                        )

            return Response({"onboarding_status": serialize_onboarding_status(profile)})

        except Exception:
            logger.exception(f"Unexpected error updating onboarding for user {user.id}")
            return Response(
                {"error": "Failed to update onboarding status"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )


class MobileDeviceViewSet(viewsets.ModelViewSet[MobileDevice]):
