class BatchOperationViewSet(viewsets.ViewSet):
    """Handle batch operations for offline sync."""

    permission_classes = [IsAuthenticated]
    throttle_classes = [DRFScopedRateThrottle]
    throttle_scope = "mobile-general"

    @action(methods=["post"], detail=False)
    def sync_changes(self, request: Request) -> Response:
        """Process multiple offline changes."""
        serializer = BatchSyncSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        changes = serializer.validated_data["changes"]
        device_id = serializer.validated_data["device_id"]

        try:
            device = MobileDevice.objects.get(
                device_id=device_id, user=cast("User", request.user)
            )
        except MobileDevice.DoesNotExist:
            return Response(
                {"error": "Device not found"}, status=status.HTTP_404_NOT_FOUND
            )

        results = []
        errors = []

        with transaction.atomic():
            for change in changes:
                change_serializer = SyncChangeSerializer(data=change)
                if not change_serializer.is_valid():
                    errors.append(
                        {"change": change, "errors": change_serializer.errors}
                    )
                    continue

                validated_change = change_serializer.validated_data

                # Create sync queue entry
                sync_item = SyncQueue.objects.create(
                    device=device,
                    operation_type=validated_change["operation_type"],
                    entity_type=validated_change["entity_type"],
                    entity_id=validated_change["entity_id"],
                    data=validated_change["data"],
                )

                # Process the change based on entity type
                try:
                    result = self._process_sync_item(sync_item, validated_change)
                    sync_item.mark_as_processed()
                    results.append(
                        {"id": str(sync_item.id), "status": "success", "result": result}
                    )
                except Exception as e:
                    sync_item.mark_as_failed(str(e))
                    errors.append(
                        {"id": str(sync_item.id), "status": "failed", "error": str(e)}
                    )

        # Update device last sync time
        device.update_last_sync()

        return Response(
            {"results": results, "errors": errors, "synced_at": device.last_sync},
            status=status.HTTP_200_OK if not errors else status.HTTP_207_MULTI_STATUS,
        )

    def _process_sync_item(
        self, sync_item: SyncQueue, change_data: dict[str, Any]
    ) -> dict[str, Any]:
        """Process individual sync item based on entity type."""
        entity_type = change_data["entity_type"]
        operation = change_data["operation_type"]
        data = change_data["data"]

        # Normalize datetime fields in data
        data = self._normalize_datetimes(data)

        # Import models dynamically to avoid circular imports
        if entity_type == "event":
            from events.models import Event
            from events.permissions import user_can_edit_event
            from events.serializers import EventSerializer

            user = sync_item.device.user

            if operation == "create":
                from users.models import FamilyMembership

                raw_family_id = data.get("family_group")
                if not raw_family_id:
                    raise PermissionDenied("family_group is required to create events.")
                family_id = uuid.UUID(str(raw_family_id))
                if not FamilyMembership.objects.filter(
                    user=user, family_id=family_id, is_active=True
                ).exists():
                    security_log_access_denied(
                        user_id=user.id,
                        action="event.create",
                        object_type="family_group",
                        object_id=str(family_id),
                        reason="family_membership_required",
                    )
                    raise PermissionDenied("Cannot create events for this family.")
                serializer = EventSerializer(data=data)
                serializer.is_valid(raise_exception=True)
                instance = serializer.save()
                return EventSerializer(instance).data
            elif operation == "update":
                # nosemgrep: clancal.security.event-objects-bypass-secure-manager
                found = Event.objects.filter(id=change_data["entity_id"]).first()
                if not found or not user_can_edit_event(user, found):
                    security_log_access_denied(
                        user_id=user.id,
                        action="event.update",
                        object_type="event",
                        object_id=str(change_data["entity_id"]),
                        reason="event_not_found_or_not_editable",
                    )
                    raise PermissionDenied("Event not found or access denied.")
                instance = found
                serializer = EventSerializer(instance, data=data, partial=True)
                serializer.is_valid(raise_exception=True)
                instance = serializer.save()
                return EventSerializer(instance).data
            elif operation == "delete":
                # nosemgrep: clancal.security.event-objects-bypass-secure-manager
                found = Event.objects.filter(id=change_data["entity_id"]).first()
                if not found or not user_can_edit_event(user, found):
                    security_log_access_denied(
                        user_id=user.id,
                        action="event.delete",
                        object_type="event",
                        object_id=str(change_data["entity_id"]),
                        reason="event_not_found_or_not_editable",
                    )
                    raise PermissionDenied("Event not found or access denied.")
                found.delete()
                return {"deleted": True}

        # Add more entity types as needed (trips, notes, etc.)

        raise ValueError(f"Unsupported entity type: {entity_type}")

    def _normalize_datetimes(self, data: dict[str, object]) -> dict[str, object]:
        """Normalize datetime fields in client data."""
        from django.utils.dateparse import parse_datetime
        from django.utils.timezone import is_naive, make_aware

        # Common datetime field names to check
        datetime_fields = [
            "start",
            "end",
            "start_time",
            "end_time",
            "created_at",
            "updated_at",
            "date",
            "datetime",
            "departure_date",
            "return_date",
            "due_date",
        ]

        for field in datetime_fields:
            if field in data and isinstance(data[field], str):
                try:
                    field_value = str(data[field])  # Already checked isinstance
                    dt = parse_datetime(field_value)
                    if dt is None:
                        # Try parsing as date-only format and convert to datetime
                        from django.utils.dateparse import parse_date

                        date_obj = parse_date(field_value)
                        if date_obj:
                            # Convert date to datetime at midnight
                            from datetime import datetime, time

                            dt = datetime.combine(date_obj, time.min)

                    if dt:
                        # Ensure timezone awareness
                        if is_naive(dt):
                            dt = make_aware(dt)
                        data[field] = dt
                except (ValueError, TypeError) as e:
                    logger.warning(
                        f"Failed to parse datetime field '{field}': {str(e)}"
                    )
                    # Leave the field as-is and let the serializer handle validation

        return data

    @action(methods=["get"], detail=False)
    def pending_sync(self, request: Request) -> Response:
        """Get pending sync items for a device."""
        from typing import cast

        device_id = request.query_params.get("device_id")

        try:
            device = MobileDevice.objects.get(
                device_id=device_id, user=cast("User", request.user)
            )
            pending_items = SyncQueue.objects.filter(
                device=device, status__in=["pending", "failed", "conflict"]
            )
            serializer = SyncQueueSerializer(pending_items, many=True)

            return Response(
                {"pending": serializer.data, "count": pending_items.count()}
            )

        except MobileDevice.DoesNotExist:
            return Response(
                {"error": "Device not found"}, status=status.HTTP_404_NOT_FOUND
            )


class ImageOptimizationView(APIView):
    """Optimize images for mobile devices."""

    permission_classes = [IsAuthenticated]
    throttle_classes = [DRFScopedRateThrottle]
    throttle_scope = "mobile-general"

    def post(self, request: Request) -> Response:
        """Resize and optimize uploaded images."""
        image_file = request.FILES.get("image")
        if not image_file:
            return Response(
                {"error": "No image provided"}, status=status.HTTP_400_BAD_REQUEST
            )

        # Validate content type
        content_type = getattr(image_file, "content_type", "")
        if not content_type.startswith("image/"):
            return Response(
                {"error": "Invalid image type"}, status=status.HTTP_400_BAD_REQUEST
            )

        size = request.data.get("size", "medium")
        try:
            quality = int(request.data.get("quality", 85))
        except (TypeError, ValueError):
            return Response(
                {"error": "Invalid quality value"}, status=status.HTTP_400_BAD_REQUEST
            )
        # Bound quality to safe range
        quality = max(1, min(quality, 95))

        try:
            image_content = image_file.read()
            original_size = len(image_content)
            content_hash = sha256(image_content).hexdigest()
            cache_key = _image_optimization_cache_key(content_hash, size, quality)
            optimized_key = _image_variant_file_key(
                content_hash, size, quality, "optimized"
            )
            thumbnail_key = _image_variant_file_key(
                content_hash, size, quality, "thumbnail"
            )
            storage = storages["s3uploadEvents"]
            request_host = request.get_host()

            cached_metadata = cache.get(cache_key)
            if isinstance(cached_metadata, dict):
                return Response(
                    _build_image_optimization_payload(cached_metadata, request_host),
                    status=status.HTTP_200_OK,
                )

            if storage.exists(optimized_key) and storage.exists(thumbnail_key):
                stored_metadata = _load_optimized_variant_metadata(
                    optimized_key,
                    thumbnail_key,
                    original_size,
                )
                cache.set(
                    cache_key,
                    stored_metadata,
                    timeout=IMAGE_OPTIMIZATION_CACHE_TTL_SECONDS,
                )
                return Response(
                    _build_image_optimization_payload(stored_metadata, request_host),
                    status=status.HTTP_200_OK,
                )

            with _open_verified_image(image_content) as source_image:
                preset_size = IMAGE_OPTIMIZATION_SIZE_PRESETS.get(size)
                needs_resize = preset_size is not None and (
                    source_image.width > preset_size[0]
                    or source_image.height > preset_size[1]
                )
                can_reuse_original = (
                    source_image.format == "JPEG"
                    and source_image.mode == "RGB"
                    and not needs_resize
                    and quality >= IMAGE_OPTIMIZATION_REUSE_QUALITY_FLOOR
                )

                if can_reuse_original:
                    optimized_bytes = image_content
                    optimized_dimensions = {
                        "width": source_image.width,
                        "height": source_image.height,
                    }
                    thumbnail_bytes = _build_image_thumbnail(source_image)
                else:
                    optimized_image = _prepare_image_for_jpeg(source_image)
                    try:
                        if preset_size:
                            optimized_image.thumbnail(
                                preset_size,
                                Image.Resampling.LANCZOS,
                            )
                        optimized_dimensions = {
                            "width": optimized_image.width,
                            "height": optimized_image.height,
                        }
                        optimized_bytes = _serialize_jpeg(optimized_image, quality)
                        thumbnail_bytes = _build_image_thumbnail(optimized_image)
                    finally:
                        optimized_image.close()

            storage.save(optimized_key, ContentFile(optimized_bytes))
            storage.save(thumbnail_key, ContentFile(thumbnail_bytes))

            metadata = {
                "optimized_key": optimized_key,
                "thumbnail_key": thumbnail_key,
                "original_size": original_size,
                "optimized_size": len(optimized_bytes),
                "dimensions": optimized_dimensions,
            }
            cache.set(
                cache_key,
                metadata,
                timeout=IMAGE_OPTIMIZATION_CACHE_TTL_SECONDS,
            )

            return Response(
                _build_image_optimization_payload(metadata, request_host),
                status=status.HTTP_200_OK,
            )
        except Image.DecompressionBombError:
            logger.error("Image decompression bomb detected")
            return Response(
                {"error": "Image too large or potentially malicious"},
                status=status.HTTP_400_BAD_REQUEST,
            )
        except (UnidentifiedImageError, OSError):
            return Response(
                {"error": "Invalid image file"},
                status=status.HTTP_400_BAD_REQUEST,
            )
        except Exception as e:
            logger.error(f"Image optimization failed: {str(e)}")
            return Response(
                {"error": "Failed to optimize image"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )


class MobileTokenRefreshView(TokenRefreshView):
    """Custom token refresh view with device validation."""

    throttle_classes = [DRFScopedRateThrottle]
    throttle_scope = "mobile-refresh"

    def post(self, request: Request, *args: Any, **kwargs: Any) -> Response:
        """Refresh token with device validation."""
        device_id = request.data.get("device_id")
        if not device_id:
            return Response(
                {"error": "Device ID required"}, status=status.HTTP_400_BAD_REQUEST
            )

        # Get the refresh token
        refresh_token = request.data.get("refresh")
        if not refresh_token:
            return Response(
                {"error": "Refresh token required"}, status=status.HTTP_400_BAD_REQUEST
            )

        try:
            refresh = RefreshToken(refresh_token)

            # Verify device ID matches
            if refresh.get("device_id") != device_id:
                raise TokenError("Device mismatch")

            # Call parent class method
            response = super().post(request, *args, **kwargs)

            # Update session last refreshed time
            if response.status_code == status.HTTP_200_OK:
                try:
                    device = MobileDevice.objects.get(device_id=device_id)
                    session = MobileSession.objects.filter(
                        device=device,
                        refresh_token_jti=str(refresh["jti"]),
                        is_active=True,
                    ).first()
                    if session:
                        session.last_refreshed = timezone.now()
                        session.save(update_fields=["last_refreshed"])
                except (MobileDevice.DoesNotExist, MobileSession.DoesNotExist):
                    pass

            return response

        except TokenError as e:
            logger.warning("Token refresh failed: %s", e)
            return Response(
                {"error": "Authentication failed. Please log in again."},
                status=status.HTTP_401_UNAUTHORIZED,
            )


class BulkEventOperationsViewSet(viewsets.ViewSet):
    """Handle bulk operations on events for mobile apps."""

    permission_classes = [IsAuthenticated]
    throttle_classes = [DRFScopedRateThrottle]
    throttle_scope = "mobile-general"

    def _get_events_from_filters_or_ids(
        self, request: Request, validated_data: dict[str, Any]
    ) -> Response | QuerySet[Event]:
        """Get events either from event_ids or from filter criteria.

        Returns:
            QuerySet of Event objects or Response with error
        """
        from typing import cast

        from events.models import Event

        user = cast("User", request.user)

        # Get user's accessible family IDs
        family_ids = list(user.family_memberships.values_list("family_id", flat=True))

        if not family_ids:
            return Response(
                {"error": "User has no family memberships"},
                status=status.HTTP_403_FORBIDDEN,
            )

        # Mode 1: Direct event selection
        if validated_data.get("event_ids"):
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            events = Event.objects.filter(
                id__in=validated_data["event_ids"], family_group_id__in=family_ids
            )
            return events

        # Mode 2: Filter-based selection
        family_group_id = validated_data.get("family_group_id")
        if family_group_id:
            if family_group_id not in family_ids:
                return Response(
                    {"error": "No permission for specified family"},
                    status=status.HTTP_403_FORBIDDEN,
                )
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            events = Event.objects.filter(family_group_id=family_group_id)
        else:
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            events = Event.objects.filter(family_group_id__in=family_ids)

        # Apply date filters
        if validated_data.get("start_date"):
            events = events.filter(start_time__gte=validated_data["start_date"])
        if validated_data.get("end_date"):
            events = events.filter(end_time__lte=validated_data["end_date"])

        # Apply visibility filter
        if validated_data.get("visibility"):
            events = events.filter(visibility=validated_data["visibility"])

        # Apply regex pattern filter
        if validated_data.get("regex_pattern"):
            try:
                import re

                pattern = re.compile(validated_data["regex_pattern"], re.IGNORECASE)
                filtered_events = [
                    event
                    for event in events
                    if pattern.search(event.title)
                    or pattern.search(event.description)
                    or pattern.search(event.location or "")
                ]
                event_ids = [event.id for event in filtered_events]
                # nosemgrep: clancal.security.event-objects-bypass-secure-manager
                events = Event.objects.filter(id__in=event_ids)
            except re.error as e:
                return Response(
                    {"error": f"Invalid regex pattern: {str(e)}"},
                    status=status.HTTP_400_BAD_REQUEST,
                )

        return events

    @action(methods=["post"], detail=False)
    def count_matching(self, request: Request) -> Response:
        """Count events matching the provided filters without modifying them.

        This endpoint is useful for showing users how many events will be affected
        before they confirm a bulk operation.
        """
        serializer = EventFilterSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        # Create a temporary dict with just the filter fields for _get_events_from_filters_or_ids
        filter_data = {
            "regex_pattern": serializer.validated_data.get("regex_pattern"),
            "start_date": serializer.validated_data.get("start_date"),
            "end_date": serializer.validated_data.get("end_date"),
            "visibility": serializer.validated_data.get("visibility"),
            "family_group_id": serializer.validated_data.get("family_group_id"),
        }

        result = self._get_events_from_filters_or_ids(request, filter_data)

        # Check if it's an error response
        if isinstance(result, Response):
            return result

        events = result
        return Response({"count": events.count()}, status=status.HTTP_200_OK)

    @action(methods=["post"], detail=False)
    def bulk_update(self, request: Request) -> Response:
        """Update multiple events at once (change visibility, move dates/times).

        Supports two modes:
        1. Direct selection: Provide event_ids
        2. Filter-based: Provide filter fields for "select all matching"
        """
        serializer = BulkUpdateSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        action_type = serializer.validated_data["action"]
        new_visibility = serializer.validated_data.get("new_visibility")
        date_offset = serializer.validated_data.get("date_offset", 0)
        time_offset = serializer.validated_data.get("time_offset", 0)

        # Get events using either mode
        result = self._get_events_from_filters_or_ids(
            request, serializer.validated_data
        )

        # Check if it's an error response
        if isinstance(result, Response):
            return result

        events = result

        if not events.exists():
            return Response(
                {"error": "No events found or insufficient permissions"},
                status=status.HTTP_404_NOT_FOUND,
            )

        results: dict[str, list[dict[str, str]]] = {"success": [], "errors": []}

        try:
            with transaction.atomic():
                for event in events:
                    try:
                        # Track external events
                        if event.is_external and event.external_id:
                            self._track_external_event_modification(event)

                        # Perform the requested action
                        if action_type == "change_visibility":
                            if new_visibility:
                                event.visibility = new_visibility
                                event.save(update_fields=["visibility"])  # type: ignore[no-untyped-call]

                        elif action_type == "move":
                            # Apply date offset (in days)
                            if date_offset:
                                event.start_time += timedelta(days=date_offset)
                                event.end_time += timedelta(days=date_offset)

                            # Apply time offset (in hours)
                            if time_offset:
                                event.start_time += timedelta(hours=time_offset)
                                event.end_time += timedelta(hours=time_offset)

                            event.save(update_fields=["start_time", "end_time"])  # type: ignore[no-untyped-call]

                        results["success"].append(
                            {"id": str(event.id), "title": event.title}
                        )

                    except Exception as e:
                        logger.error(f"Failed to update event {event.id}: {str(e)}")
                        results["errors"].append(
                            {
                                "id": str(event.id),
                                "title": event.title,
                                "error": str(e),
                            }
                        )

            return Response(
                {
                    "results": results,
                    "updated_count": len(results["success"]),
                    "error_count": len(results["errors"]),
                },
                status=status.HTTP_200_OK,
            )

        except Exception as e:
            logger.error(f"Bulk update failed: {str(e)}")
            return Response(
                {"error": "Bulk update operation failed"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(methods=["post"], detail=False)
    def bulk_delete(self, request: Request) -> Response:
        """Delete multiple events at once.

        Supports two modes:
        1. Direct selection: Provide event_ids
        2. Filter-based: Provide filter fields for "select all matching"
        """
        serializer = BulkDeleteSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        # Get events using either mode
        result = self._get_events_from_filters_or_ids(
            request, serializer.validated_data
        )

        # Check if it's an error response
        if isinstance(result, Response):
            return result

        events = result

        if not events.exists():
            return Response(
                {"error": "No events found or insufficient permissions"},
                status=status.HTTP_404_NOT_FOUND,
            )

        results: dict[str, list[dict[str, str]]] = {"success": [], "errors": []}

        try:
            with transaction.atomic():
                for event in events:
                    try:
                        event_data = {"id": str(event.id), "title": event.title}

                        # Track external event deletion
                        if event.is_external and event.external_id:
                            self._track_external_event_deletion(event)

                        event.delete()
                        results["success"].append(event_data)

                    except Exception as e:
                        logger.error(f"Failed to delete event {event.id}: {str(e)}")
                        results["errors"].append(
                            {
                                "id": str(event.id),
                                "title": event.title,
                                "error": str(e),
                            }
                        )

            return Response(
                {
                    "results": results,
                    "deleted_count": len(results["success"]),
                    "error_count": len(results["errors"]),
                },
                status=status.HTTP_200_OK,
            )

        except Exception as e:
            logger.error(f"Bulk delete failed: {str(e)}")
            return Response(
                {"error": "Bulk delete operation failed"},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    @action(methods=["post"], detail=False)
    def filter_events(self, request: Request) -> Response:
        """Filter events with advanced criteria including regex patterns."""
        from typing import cast

        user = cast("User", request.user)

        serializer = EventFilterSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        regex_pattern = serializer.validated_data.get("regex_pattern")
        start_date = serializer.validated_data.get("start_date")
        end_date = serializer.validated_data.get("end_date")
        visibility = serializer.validated_data.get("visibility")
        family_group_id = serializer.validated_data.get("family_group_id")
        limit = serializer.validated_data.get("limit")
        offset = serializer.validated_data.get("offset") or 0

        # Import Event and EventSerializer
        from events.models import Event
        from events.serializers import EventSerializer

        # Get user's accessible family IDs
        family_ids = list(user.family_memberships.values_list("family_id", flat=True))

        if not family_ids:
            return Response(
                {"error": "User has no family memberships"},
                status=status.HTTP_403_FORBIDDEN,
            )

        # Start with base queryset
        if family_group_id:
            # Verify user has access to specified family
            if family_group_id not in family_ids:
                return Response(
                    {"error": "No permission for specified family"},
                    status=status.HTTP_403_FORBIDDEN,
                )
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            events = Event.objects.filter(family_group_id=family_group_id)
        else:
            # nosemgrep: clancal.security.event-objects-bypass-secure-manager
            events = Event.objects.filter(family_group_id__in=family_ids)

        # Apply date filters
        if start_date:
            events = events.filter(start_time__gte=start_date)
        if end_date:
            events = events.filter(end_time__lte=end_date)

        # Apply visibility filter
        if visibility:
            events = events.filter(visibility=visibility)

        # Apply regex pattern filter
        if regex_pattern:
            try:
                import re

                # Get all events that match the pattern
                pattern = re.compile(regex_pattern, re.IGNORECASE)
                filtered_events = [
                    event
                    for event in events
                    if pattern.search(event.title)
                    or pattern.search(event.description)
                    or pattern.search(event.location or "")
                ]
                event_ids = [event.id for event in filtered_events]
                # nosemgrep: clancal.security.event-objects-bypass-secure-manager
                events = Event.objects.filter(id__in=event_ids)
            except re.error as e:
                return Response(
                    {"error": f"Invalid regex pattern: {str(e)}"},
                    status=status.HTTP_400_BAD_REQUEST,
                )

        # Order by start time
        events = events.order_by("start_time")
        total_count = events.count()

        if limit is not None:
            events = events[offset : offset + limit]

        # Serialize and return
        output_serializer = EventSerializer(events, many=True)
        return Response(
            {"events": output_serializer.data, "count": total_count},
            status=status.HTTP_200_OK,
        )

    def _track_external_event_deletion(self, event: Event) -> None:
        """Track deletion of external calendar events."""
        if not event.is_external or not event.external_id:
            return

        try:
            # Import models
            from calendars.models import DeletedExternalEvent, ExternalCalendarAccount

            # Find the external calendar account
            calendar = ExternalCalendarAccount.objects.filter(
                calendar_id=event.calendar_id,
                user__family_memberships__family_id=event.family_group_id,
            ).first()

            if calendar:
                # Create deletion record
                DeletedExternalEvent.objects.get_or_create(
                    calendar=calendar, external_id=event.external_id
                )
                logger.info(
                    f"Tracked deletion of external event {event.external_id} "
                    f"from calendar {calendar.id}"
                )
        except Exception as e:
            logger.error(
                f"Failed to track external event deletion for {event.id}: {str(e)}"
            )

    def _track_external_event_modification(self, event: Event) -> None:
        """Track modification of external calendar events."""
        if not event.is_external or not event.external_id:
            return

        try:
            # Import models
            from calendars.models import (
                ExternalCalendarAccount,
                ModifiedExternalEvent,
            )

            # Find the external calendar account
            calendar = ExternalCalendarAccount.objects.filter(
                calendar_id=event.calendar_id,
                user__family_memberships__family_id=event.family_group_id,
            ).first()

            if calendar:
                # Create or update modification record
                ModifiedExternalEvent.objects.update_or_create(
                    calendar=calendar,
                    external_id=event.external_id,
                    defaults={"event": event, "modified_at": timezone.now()},
                )
                logger.info(
                    f"Tracked modification of external event {event.external_id} "
                    f"from calendar {calendar.id}"
                )
        except Exception as e:
            logger.error(
                f"Failed to track external event modification for {event.id}: {str(e)}"
            )

