    @action(methods=["post"], detail=False)
    def revoke_token(self, request: Request) -> Response:
        """Revoke refresh token on logout."""
        serializer = TokenRevokeSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        refresh_token = serializer.validated_data["refresh"]
        device_id = serializer.validated_data["device_id"]

        try:
            token = RefreshToken(refresh_token)

            # Revoke the session
            device = MobileDevice.objects.filter(device_id=device_id).first()
            if device:
                session = MobileSession.objects.filter(
                    device=device,
                    refresh_token_jti=str(token.payload.get("jti")),
                    is_active=True,
                ).first()
                if session:
                    session.revoke()

                # Update device logout time
                device.last_logout = timezone.now()
                device.save(update_fields=["last_logout"])

            # Blacklist the token
            token.blacklist()

            logger.info(f"Token revoked for device {device_id}")
            return Response({"status": "revoked"}, status=status.HTTP_200_OK)

        except Exception as e:
            logger.error(f"Token revocation failed: {str(e)}")
            return Response(
                {"error": "Failed to revoke token"}, status=status.HTTP_400_BAD_REQUEST
            )

    @action(methods=["post"], detail=False, permission_classes=[IsAuthenticated])
    def enable_biometric(self, request: Request) -> Response:
        """Enable biometric authentication for a device."""
