                device_id=device_id, user=cast("User", request.user)
            )
            device.biometric_enabled = True
            device.save(update_fields=["biometric_enabled"])

            return Response({"status": "enabled"}, status=status.HTTP_200_OK)

        except MobileDevice.DoesNotExist:
