def _represented_member_count_from_instance(obj: FamilyGroup) -> int:
    annotated_count = getattr(obj, "represented_member_count", None)
    if annotated_count is not None:
        return int(annotated_count)

    if (
        hasattr(obj, "_prefetched_objects_cache")
        and "party_units" in obj._prefetched_objects_cache
    ):
        total = 0
        for party_unit in obj.party_units.all():
            if (
                hasattr(party_unit, "_prefetched_objects_cache")
                and "represented_members" in party_unit._prefetched_objects_cache
            ):
                total += len(party_unit.represented_members.all())
            else:
                return RepresentedGroupMember.objects.filter(
                    party_unit__group=obj
                ).count()
        return total

