class SerializerSpanMixin:
    def to_representation(self, instance):  # type: ignore[misc]
        serializer_name = self.__class__.__name__
        with tracer.start_as_current_span(f"serializer.{serializer_name}") as span:
            if span.is_recording():
                span.set_attribute("serializer.class", serializer_name)
                if hasattr(instance, "_meta"):
                    span.set_attribute(
                        "serializer.model",
                        f"{instance._meta.app_label}.{instance._meta.model_name}",
                    )
                    pk = getattr(instance, "pk", None)
                    if pk is not None:
                        span.set_attribute("serializer.pk", str(pk))
            return super().to_representation(instance)  # type: ignore[misc]


class RequestCacheMixin:
    """
    Cache serializer results within a single request to avoid re-serializing
    the same objects multiple times (e.g., when the same user appears in
    multiple places in a response).

    This mixin should be placed BEFORE SerializerSpanMixin in the inheritance
    order so that the telemetry span still wraps the full serialization.
    """

    def to_representation(self, instance):  # type: ignore[misc]
        request = self.context.get("request")  # type: ignore[attr-defined]
        if not request:
            return super().to_representation(instance)  # type: ignore[misc]

        # Create cache attribute on request if it doesn't exist
        cache_attr = "_serializer_cache"
        if not hasattr(request, cache_attr):
            setattr(request, cache_attr, {})

        # Generate cache key from serializer class and instance pk
        cache_key = f"{self.__class__.__name__}:{instance.pk}"
        cache = getattr(request, cache_attr)

        # Return cached result if available
        if cache_key in cache:
            return cache[cache_key]

        # Serialize and cache the result
        result = super().to_representation(instance)  # type: ignore[misc]
        cache[cache_key] = result
        return result


