            "avatar_url",
            "has_social_account",
            "profile",
            "feature_flags",
        ]  # <-- Add has_social_account here too

    def get_avatar_url(self, obj):
        """
        Get the avatar URL from SocialAccount (preferring Google)
        or Child profile picture.
        """
        # Try Child profile first if it exists
        prefetched_children = getattr(obj, "_prefetched_objects_cache", {}).get(
            "child_profile"
        )
        if prefetched_children is None:
            self._maybe_log_related_miss(obj, "child_profile")
        if prefetched_children is not None:
            child_profile = prefetched_children[0] if prefetched_children else None
        else:
            child_profile = obj.child_profile.first()
        if (
            child_profile
            and child_profile.profile_picture
            and hasattr(child_profile.profile_picture, "name")
            and child_profile.profile_picture.name
        ):
            # Use the MediaStorageService to generate the URL using the file key (name)
            # This ensures the correct endpoint_url (public or internal) is used.
            return MediaStorageService.generate_presigned_url(
                child_profile.profile_picture.name
            )

        # Try Google SocialAccount next

        prefetched_social_accounts = getattr(obj, "_prefetched_objects_cache", {}).get(
            "socialaccount_set"
        )
        if prefetched_social_accounts is None:
            self._maybe_log_related_miss(obj, "socialaccount_set")
        if prefetched_social_accounts is not None:
            google_account = next(
                (
                    account
                    for account in prefetched_social_accounts
                    if account.provider == "google"
                ),
                None,
            )
            if google_account and "picture" in google_account.extra_data:
                return google_account.extra_data["picture"]
        else:
            try:
                google_account = obj.socialaccount_set.filter(provider="google").first()
                if google_account and "picture" in google_account.extra_data:
                    return google_account.extra_data["picture"]
            except SocialAccount.DoesNotExist:
                pass  # No Google social account linked

        # Fallback: Try any other social account
        if prefetched_social_accounts is not None:
            social_account = (
                prefetched_social_accounts[0] if prefetched_social_accounts else None
            )
        else:
            social_account = obj.socialaccount_set.first()
        if social_account and "picture" in social_account.extra_data:
            # Attempt common keys, might need adjustment for other providers
            return social_account.extra_data.get(
                "picture", social_account.extra_data.get("avatar_url")
            )

        # Final fallback
        return None

    def get_has_social_account(self, obj):  # <-- Add this method
        """Check if the user has any linked social accounts."""
        prefetched_social_accounts = getattr(obj, "_prefetched_objects_cache", {}).get(
            "socialaccount_set"
        )
        if prefetched_social_accounts is None:
            self._maybe_log_related_miss(obj, "socialaccount_set")
        if prefetched_social_accounts is not None:
            return bool(prefetched_social_accounts)
        return obj.socialaccount_set.exists()

    def get_profile(self, obj):
        """Return the user's profile data."""
        from users.utils import serialize_onboarding_status

        profile_cached = "profile" in getattr(obj, "_state", {}).fields_cache  # type: ignore[union-attr]
        if not profile_cached:
            self._maybe_log_related_miss(obj, "profile")
        if hasattr(obj, "profile"):
            profile = obj.profile
            return {
                "id": profile.id,  # Include profile ID for updates
                "primary_family": str(profile.primary_family.id)
                if profile.primary_family
                else None,
                "birth_date": profile.birth_date.isoformat()
                if profile.birth_date
                else None,
                "phone_number": profile.phone_number,
                "color": profile.color,
                "timezone": profile.timezone,
                "address": profile.address,
                "bio": profile.bio,
                "emergency_contact_name": profile.emergency_contact_name,
                "emergency_contact_phone": profile.emergency_contact_phone,
                "onboarding_status": serialize_onboarding_status(profile),
            }
        return None

    def _maybe_log_related_miss(self, obj, relation_name):
        if not logger.isEnabledFor(logging.DEBUG):
            return
        cache = getattr(self, "_related_cache_miss_logged", None)
        if cache is None:
            cache = set()
            self._related_cache_miss_logged = cache
        cache_key = (obj.pk, relation_name)
        if cache_key in cache:
            return
        cache.add(cache_key)
        logger.debug(
            "UserSerializer related cache miss relation=%s user_id=%s",
            relation_name,
            obj.pk,
        )

    def get_feature_flags(self, obj):
        # Cache feature flags per-request to avoid repeated external service calls
        request = self.context.get("request")
        cache_key = f"feature_flags:{obj.pk}"

        if request:
            if not hasattr(request, "_feature_flag_cache"):
                request._feature_flag_cache = {}
            if cache_key in request._feature_flag_cache:
                return request._feature_flag_cache[cache_key]

        try:
            enabled = frames_feature_flags.is_enabled(obj)
        except Exception:
            enabled = True

        result = {"frames_enabled": bool(enabled)}

        if request:
            request._feature_flag_cache[cache_key] = result

        return result


