class FamilyGroupSerializer(
    RequestCacheMixin, SerializerSpanMixin, serializers.ModelSerializer
):
    """Serializer for the FamilyGroup model"""

    # Read field - returns the current family type
    family_type = serializers.SerializerMethodField()
    group_kind = serializers.SerializerMethodField()
    is_home_group = serializers.SerializerMethodField()
    is_hidden = serializers.BooleanField(read_only=True)
    party_unit_count = serializers.SerializerMethodField()
    represented_member_count = serializers.SerializerMethodField()
    # Write field - accepts group kind when creating
    family_type_input = serializers.ChoiceField(
        choices=["IMMEDIATE", "EXTENDED", "META", "TEAM", "CIRCLE"],
        write_only=True,
        required=False,
        default="IMMEDIATE",
    )
    group_kind_input = serializers.ChoiceField(
        choices=["IMMEDIATE", "EXTENDED", "META", "TEAM", "CIRCLE"],
        write_only=True,
        required=False,
    )
    feature_settings = FamilyFeatureSettingsSerializer(read_only=True)
    is_direct_member = serializers.SerializerMethodField()
    admin_name = serializers.SerializerMethodField()
    member_count = serializers.SerializerMethodField()

    class Meta:
        model = FamilyGroup
        fields = [
            "id",
            "name",
            "description",
            "referral_code",
            "created_at",
            "updated_at",
            "family_type",
            "group_kind",
            "is_home_group",
            "is_hidden",
            "family_type_input",
            "group_kind_input",
            "network_invite_policy",
            "feature_settings",
            "is_direct_member",
            "admin_name",
            "member_count",
            "party_unit_count",
            "represented_member_count",
        ]
        read_only_fields = [
            "referral_code",
            "created_at",
            "updated_at",
            "family_type",
            "group_kind",
            "is_home_group",
            "is_hidden",
            "party_unit_count",
            "represented_member_count",
        ]

    def _get_group_kind(self, obj: FamilyGroup) -> str | None:
        # Check if group_type was prefetched via select_related
        # The _state.fields_cache holds select_related results
        group_type_cached = "group_type" in getattr(obj, "__dict__", {})
        if not group_type_cached:
            # Log cache miss for debugging N+1 queries
            logger.debug(
                "FamilyGroupSerializer related cache miss relation=group_type family_id=%s",
                obj.pk,
            )
        if hasattr(obj, "group_type") and obj.group_type:
            return obj.group_type.type
        return None

    def get_family_type(self, obj):
        """Backward-compatible alias for group kind."""
        return self._get_group_kind(obj)

    def get_group_kind(self, obj):
        return self._get_group_kind(obj)

    def get_is_home_group(self, obj: FamilyGroup) -> bool:
        request = self.context.get("request")
        user = getattr(request, "user", None)
        if not user or not user.is_authenticated:
            return False
        profile = getattr(user, "profile", None)
        return bool(profile and profile.primary_family_id == obj.id)

    def get_is_direct_member(self, obj: FamilyGroup) -> bool:
        """Check if the request user has a direct FamilyMembership for this family."""
        direct_family_ids = self.context.get("direct_family_ids")
        if direct_family_ids is not None:
            return obj.pk in direct_family_ids
        # Fallback: check via DB (should not normally be needed)
        request = self.context.get("request")
        if request and hasattr(request, "user") and request.user.is_authenticated:
            return FamilyMembership.objects.filter(
                user=request.user, family=obj
            ).exists()
        return False

    def get_admin_name(self, obj):
        """Return the first name of the first active organizer/admin for disambiguation."""
        # Use prefetched memberships if available
        if (
            hasattr(obj, "_prefetched_objects_cache")
            and "memberships" in obj._prefetched_objects_cache
        ):
            for m in obj.memberships.all():
                if m.is_active and (m.is_admin or m.role in {"PARENT", "ORGANIZER"}):
                    return m.user.first_name or m.user.username
            return None
        membership = (
            obj.memberships.filter(is_active=True)
            .filter(Q(is_admin=True) | Q(role="PARENT") | Q(role="ORGANIZER"))
            .select_related("user")
            .first()
        )
        if membership and membership.user:
            return membership.user.first_name or membership.user.username
        return None

    def get_member_count(self, obj):
        """Return the number of active members."""
        # Use prefetched memberships if available
        if (
            hasattr(obj, "_prefetched_objects_cache")
            and "memberships" in obj._prefetched_objects_cache
        ):
            return sum(1 for m in obj.memberships.all() if m.is_active)
        return obj.memberships.filter(is_active=True).count()

    def get_party_unit_count(self, obj: FamilyGroup) -> int:
        if (
            hasattr(obj, "_prefetched_objects_cache")
            and "party_units" in obj._prefetched_objects_cache
        ):
            return len(obj.party_units.all())
        return obj.party_units.count()

    def get_represented_member_count(self, obj: FamilyGroup) -> int:
        return _represented_member_count_from_instance(obj)

    def validate(self, attrs):
        group_kind_input = attrs.pop("group_kind_input", None)
        if group_kind_input:
            attrs["family_type_input"] = group_kind_input
        return super().validate(attrs)


