            "id",
            "name",
            "description",
            "referral_code",
            "created_at",
            "updated_at",
            "family_type",
            "group_kind",
            "is_home_group",
            "is_hidden",
            "network_invite_policy",
            "feature_settings",
            "admin_name",
            "member_count",
            "party_unit_count",
            "represented_member_count",
        ]
        read_only_fields = fields

    def _get_group_kind(self, obj: FamilyGroup) -> str | None:
        group_type_cached = "group_type" in getattr(obj, "__dict__", {})
        if not group_type_cached:
            logger.debug(
                "FamilyGroupSerializerLite cache miss relation=group_type family_id=%s",
                obj.pk,
            )
        if hasattr(obj, "group_type") and obj.group_type:
            return obj.group_type.type
        return None

    def get_family_type(self, obj):
        """Backward-compatible alias for group kind."""
        return self._get_group_kind(obj)

    def get_group_kind(self, obj):
        return self._get_group_kind(obj)

    def get_is_home_group(self, obj: FamilyGroup) -> bool:
        request = self.context.get("request")
        user = getattr(request, "user", None)
        if not user or not user.is_authenticated:
            return False
        profile = getattr(user, "profile", None)
        return bool(profile and profile.primary_family_id == obj.id)

    def get_admin_name(self, obj):
        """Return the first name of the first active organizer/admin for disambiguation."""
        membership = (
            obj.memberships.filter(is_active=True)
            .filter(Q(is_admin=True) | Q(role="PARENT") | Q(role="ORGANIZER"))
            .select_related("user")
            .first()
        )
        if membership and membership.user:
            return membership.user.first_name or membership.user.username
        return None

    def get_member_count(self, obj):
        """Return the number of active members."""
        return obj.memberships.filter(is_active=True).count()

    def get_party_unit_count(self, obj: FamilyGroup) -> int:
        return obj.party_units.count()

    def get_represented_member_count(self, obj: FamilyGroup) -> int:
        return _represented_member_count_from_instance(obj)


