class GroupPartyUnitSerializer(SerializerSpanMixin, serializers.ModelSerializer):
    group_detail = FamilyGroupSerializerLite(source="group", read_only=True)
    members = GroupPartyUnitMemberSerializer(many=True, read_only=True)
    represented_members = RepresentedGroupMemberSerializer(many=True, read_only=True)
    member_user_ids = serializers.ListField(
        child=serializers.IntegerField(min_value=1),
        write_only=True,
        required=False,
    )

    class Meta:
        model = GroupPartyUnit
        fields = [
            "id",
            "group",
            "group_detail",
            "name",
            "description",
            "member_user_ids",
            "members",
            "represented_members",
            "created_at",
            "updated_at",
        ]
        read_only_fields = [
            "id",
            "group_detail",
            "members",
            "represented_members",
            "created_at",
            "updated_at",
        ]

    def validate(self, attrs):
        attrs = super().validate(attrs)
        request = self.context.get("request")
        user = getattr(request, "user", None)

        group = attrs.get("group") or getattr(self.instance, "group", None)
        if group is None:
            return attrs

        if self.instance and "group" in attrs and attrs["group"] != self.instance.group:
            raise serializers.ValidationError(
                {"group": "Group cannot be changed once a party unit is created."}
            )

        _validate_party_unit_group_kind(group, "group")

        member_user_ids = attrs.get("member_user_ids")
        if member_user_ids is None:
            return attrs

        if (
            self.instance
            and not member_user_ids
            and not getattr(user, "is_staff", False)
        ):
            raise serializers.ValidationError(
                {
                    "member_user_ids": (
                        "Party units must include at least one direct group member."
                    )
                }
            )

        valid_member_ids = set(
            FamilyMembership.objects.filter(
                family=group,
                is_active=True,
                user_id__in=member_user_ids,
            ).values_list("user_id", flat=True)
        )
        if set(member_user_ids) != valid_member_ids and not getattr(
            user, "is_staff", False
        ):
            raise serializers.ValidationError(
                {
                    "member_user_ids": (
                        "All party unit members must be direct members of the selected group."
                    )
                }
            )

        return attrs

    def create(self, validated_data):
        member_user_ids = validated_data.pop("member_user_ids", [])
        with transaction.atomic():
            party_unit = GroupPartyUnit.objects.create(**validated_data)
            for user_id in member_user_ids:
                GroupPartyUnitMember.objects.get_or_create(
                    party_unit=party_unit, user_id=user_id
                )
        return party_unit

    def update(self, instance, validated_data):
        member_user_ids = validated_data.pop("member_user_ids", None)
        with transaction.atomic():
            instance = super().update(instance, validated_data)
            if member_user_ids is not None:
                instance.members.exclude(user_id__in=member_user_ids).delete()
                for user_id in member_user_ids:
                    GroupPartyUnitMember.objects.get_or_create(
                        party_unit=instance, user_id=user_id
                    )
        return instance


