class JoinFamilyByReferralSerializer(SerializerSpanMixin, serializers.Serializer):
    """Serializer for joining a family using a referral code post-signup"""

    referral_code = serializers.CharField(max_length=20, write_only=True)

    def validate_referral_code(self, value):
        """Validate the referral code corresponds to an IMMEDIATE family."""
        try:
            family = FamilyGroup.objects.select_related("group_type").get(
                referral_code=value
            )
            # Ensure the family has a type defined and it's IMMEDIATE
            if (
                not hasattr(family, "group_type")
                or family.group_type.type != "IMMEDIATE"
            ):
                raise serializers.ValidationError(
                    "This referral code does not belong to an Immediate Family group."
                )
            # Store the validated family object in context for the view
            self.context["target_family"] = family
        except FamilyGroup.DoesNotExist:
            raise serializers.ValidationError("Invalid referral code.") from None
        except FamilyGroupType.DoesNotExist:
            # Should ideally not happen if signals/save methods ensure type creation
            raise serializers.ValidationError(
                "Family type definition missing for this group."
            ) from None

        return value

    def create(self, validated_data):
        validated_data.pop("confirm_password")
        user = User.objects.create_user(**validated_data)
        return user


