class FamilyJoinRequestCreateSerializer(
    SerializerSpanMixin, serializers.ModelSerializer
):
    """Serializer for creating a FamilyJoinRequest"""

    referral_code = serializers.CharField(write_only=True)

    class Meta:
        model = FamilyJoinRequest
        fields = ["referral_code", "role", "message"]

    def validate_referral_code(self, value):
        """Validate that the referral code exists"""
        try:
            FamilyGroup.objects.get(referral_code=value)
        except FamilyGroup.DoesNotExist:
            raise serializers.ValidationError("Invalid referral code") from None
        return value

    def create(self, validated_data):
        referral_code = validated_data.pop("referral_code")
        user = self.context["request"].user
        family = FamilyGroup.objects.get(referral_code=referral_code)

        # Check if user is already a member of this family
        if FamilyMembership.objects.filter(user=user, family=family).exists():
            raise serializers.ValidationError("You are already a member of this family")

        # Check if there's already a pending request
        if FamilyJoinRequest.objects.filter(
            user=user, family=family, status="PENDING"
        ).exists():
            raise serializers.ValidationError(
                "You already have a pending request to join this family"
            )

        return submit_family_join_request(
            user=user,
            family=family,
            role=validated_data.get("role", "OTHER"),
            message=validated_data.get("message", ""),
        ).join_request


