class FamilyRelationshipCreateSerializer(
    SerializerSpanMixin, serializers.ModelSerializer
):
    """Serializer for creating a FamilyRelationship"""

    class Meta:
        model = FamilyRelationship
        fields = ["primary_family", "related_family", "relationship_type"]

    def validate(self, data):
        """Validate that the primary and related families are different"""
        if data["primary_family"] == data["related_family"]:
            raise serializers.ValidationError(
                "A family cannot have a relationship with itself"
            )

        # Check if a relationship already exists between these families
        if FamilyRelationship.objects.filter(
            primary_family=data["primary_family"], related_family=data["related_family"]
        ).exists():
            raise serializers.ValidationError(
                "A relationship already exists between these families"
            )

        return data


