class MetaFamilyMembershipCreateSerializer(
    SerializerSpanMixin, serializers.ModelSerializer
):
    """Serializer for creating a MetaFamilyMembership"""

    class Meta:
        model = MetaFamilyMembership
        fields = ["family", "meta_family"]

    def validate(self, data):
        """Validate that the family and meta family are different"""
        if data["family"] == data["meta_family"]:
            raise serializers.ValidationError("A family cannot be a member of itself")

        # Check if a membership already exists
        if MetaFamilyMembership.objects.filter(
            family=data["family"], meta_family=data["meta_family"]
        ).exists():
            raise serializers.ValidationError(
                "This family is already a member of the meta family"
            )

        # Check that the meta_family is actually a meta family
        try:
            family_type = FamilyGroupType.objects.get(family=data["meta_family"])
            if family_type.type != "META":
                raise serializers.ValidationError(
                    "The target family is not a meta family group"
                )
        except FamilyGroupType.DoesNotExist:
            raise serializers.ValidationError(
                "The target family does not have a type defined"
            ) from None

        return data


