            raise serializers.ValidationError("Invalid submission.")
        return value

    def validate_form_loaded_at(self, value: float) -> float:
        import time

        elapsed = time.time() - value
        if elapsed < 2:
            raise serializers.ValidationError("Invalid submission.")
        if elapsed > 3600:
            raise serializers.ValidationError("Invalid submission.")
        return value

